    sort_order smallint NOT NULL,
    product_id bigint NOT NULL,
    CONSTRAINT product_image_role_check CHECK (((role)::text = ANY (ARRAY[('FRONT'::character varying)::text, ('BACK'::character varying)::text, ('ADDITIONAL'::character varying)::text])))
);


