--

CREATE TABLE public.refund_request (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    detail_reason text NOT NULL,
    reason character varying(30) NOT NULL,
    rejection_reason text,
    reviewed_at timestamp(6) without time zone,
    status character varying(20) NOT NULL,
    order_id bigint NOT NULL,
    CONSTRAINT refund_request_reason_check CHECK (((reason)::text = ANY (ARRAY[('NOT_AS_DESCRIBED'::character varying)::text, ('UNDISCLOSED_DEFECT'::character varying)::text, ('NOT_SHIPPED'::character varying)::text, ('DUPLICATE_PAYMENT'::character varying)::text, ('SYSTEM_ERROR'::character varying)::text]))),
    CONSTRAINT refund_request_status_check CHECK (((status)::text = ANY (ARRAY[('REQUESTED'::character varying)::text, ('APPROVED'::character varying)::text, ('REJECTED'::character varying)::text])))
);


